    var list = new List<int> {1,2,3};
    list.Clear(); // Count==0

    var dict = new Dictionary<string,int> {{"a",1},{"b":2}};
    dict.Clear(); // Count==0

    int n = 42;
    n = 0;

    // Console.Write("\x1b[2J\x1b[H"); // ANSI clear
  }
